const rows = $input.all();

// Build a readable summary from the sheet rows.
const validRows = rows.filter(row => row.json.Name && row.json.Course);

if (validRows.length === 0) {
  return [];
}

const summary = validRows.map(row =>
  `Name: ${row.json.Name}\nCourse: ${row.json.Course}\nStatus: ${row.json.Status || "Not specified"}`
).join("\n\n");

const subject = "Course Status Summary";
const body = `Hi,

Here is the latest course status summary:

${summary}

Regards,
Your Automation Bot`;

return [{
  json: { subject, body }
}];

// Understand the Important Code
// $input.all() retrieves all rows from Google Sheets.
// filter() removes rows missing a name or course.
// map() converts each row into readable text.
// join() combines the records.
// return sends one structured item to the Gmail node.

// Important Notes
// n8n's Code node supports JavaScript.
// Returning [] prevents a blank email when no valid rows exist.
// No email is sent in this step.
